function riskManagementData() { return Object.fromEntries(riskManagementFields.map(field => [field, $(`rm${field.charAt(0).toUpperCase()}${field.slice(1)}`).value])); }
function riskRatingFromScore(likelihood, impact) { const score = Number(likelihood || 0) * Number(impact || 0); return score >= 20 ? 'Very High' : score >= 11 ? 'High' : score >= 5 ? 'Medium' : score >= 3 ? 'Low' : score ? 'Very Low' : ''; }
function updateRiskCalculations() { const assetValue = ['rmAssetConfidentiality', 'rmAssetIntegrity', 'rmAssetAvailability'].map(id => Number($(id).value) || 0).reduce((sum, value) => sum + value, 0); $('rmAssetValue').value = assetValue || ''; $('rmRiskRating').value = riskRatingFromScore($('rmLikelihood').value, $('rmImpact').value); $('rmResidualRating').value = riskRatingFromScore($('rmResidualLikelihood').value, $('rmResidualImpact').value); }
function synchronizeRiskDropdowns() { const fields = [['riskCategory', 'riskCategory'], ['effectedAsset', 'effectedAsset'], ['riskOwner', 'riskOwner'], ['treatmentAction', 'treatmentAction']]; const source = [...riskDropdowns, ...fallbackRiskDropdowns]; fields.forEach(([field, rowField]) => riskManagementRows.forEach(row => { if (row[rowField]) source.push({ fieldName: field, optionValue: row[rowField], sortOrder: 999 }); })); riskDropdowns = [...new Map(source.filter(row => row.optionValue).map(row => [`${row.fieldName}:${row.optionValue}`, row])).values()]; }
