  const impact = group('Impact'); const impactScores = [...new Set(impact.map(row => row.score))];
  $('riskIndicatorsImpactBody').innerHTML = impactScores.map(score => { const rows = impact.filter(row => row.score === score); const description = rows.find(row => row.label === 'Deskripsi Dampak'); return `<tr><td class="indicator-score">${score}</td><td>${escapeHtml(description?.description || '-')}</td>${['Layanan', 'Keuangan', 'Reputasi', 'Hukum'].map(label => `<td>${escapeHtml(rows.find(row => row.label === label)?.description || '-')}</td>`).join('')}${actions(description || rows[0] || {})}</tr>`; }).join('');
