async function saveRiskIndicator(event) { event.preventDefault(); const id = $('riskIndicatorId').value; const data = { indicatorType: $('riskIndicatorType').value, score: $('riskIndicatorScore').value, label: $('riskIndicatorLabel').value, sortOrder: $('riskIndicatorSort').value, description: $('riskIndicatorDescription').value }; const response = await fetch(id ? `/api/risk-management/indicators/${id}` : '/api/risk-management/indicators', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); if (response.ok) { resetRiskIndicatorForm(); await loadRiskManagement(); } }
async function deleteRiskIndicator(id) { if (!confirm('Delete this indicator?')) return; const response = await fetch(`/api/risk-management/indicators/${id}`, { method: 'DELETE' }); if (response.ok) await loadRiskManagement(); }

